import json, re, sys
sys.path.insert(0, '_tools')
import bl_intake as b

def run(argv, *a, **k):
    s = ' '.join(argv)
    if argv[:3] == ['git', 'remote', 'get-url']:
        return 0, 'https://gitlab.example.com/org/repo.git\n', ''
    if 'auth status' in s:
        return 0, '', ''
    m = re.search(r'pipelines/(\d+)/jobs', s)
    if m:
        old_red = m.group(1) == '85'
        return 0, json.dumps([{'id': 7, 'name': 'kb-tests', 'status': 'failed', 'failure_reason': 'script_failure', 'started_at': '2026-01-01T00:00:00Z'}] if old_red else [{'id': 8, 'name': 'kb-tests', 'status': 'manual'}]), ''
    if 'pipelines?ref=main' in s:
        return 0, json.dumps([{'id': i, 'sha': 'a' * 40, 'web_url': 'u', 'status': 'success'} for i in range(100, 0, -1)]), ''
    if '/trace' in s:
        return 0, 'FAILED t.py::f - x', ''
    return 1, '', 'unexpected ' + s
p, note = b.latest_pipeline('.', None, run)
